import{_ as t,o,c as r,a5 as a}from"./chunks/framework.BfQ7H7Qx.js";const g=JSON.parse('{"title":"Multi-Platform Trend Crawler Pipeline, Proxy Rotation, S3 Cold Storage & Daily Replay","description":"","frontmatter":{},"headers":[],"relativePath":"feature/modules/05-ai-rag-and-crawler/multiplatform-trend-crawler-pipeline/spec.md","filePath":"feature/modules/05-ai-rag-and-crawler/multiplatform-trend-crawler-pipeline/spec.md"}'),n={name:"feature/modules/05-ai-rag-and-crawler/multiplatform-trend-crawler-pipeline/spec.md"};function d(i,e,l,c,s,p){return o(),r("div",null,[...e[0]||(e[0]=[a('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Category Index</a> · <a href="./../../README.html">← Modules Master Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="multi-platform-trend-crawler-pipeline-proxy-rotation-s3-cold-storage-daily-replay" tabindex="-1">Multi-Platform Trend Crawler Pipeline, Proxy Rotation, S3 Cold Storage &amp; Daily Replay <a class="header-anchor" href="#multi-platform-trend-crawler-pipeline-proxy-rotation-s3-cold-storage-daily-replay" aria-label="Permalink to &quot;Multi-Platform Trend Crawler Pipeline, Proxy Rotation, S3 Cold Storage &amp; Daily Replay&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Module Slug</strong></td><td style="text-align:left;"><code>multiplatform-trend-crawler-pipeline</code></td></tr><tr><td style="text-align:left;"><strong>Category</strong></td><td style="text-align:left;"><code>05-ai-rag-and-crawler</code> — AI Trend Crawler, Neo4j Knowledge Graph &amp; Brand RAG</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Admin</code></td></tr><tr><td style="text-align:left;"><strong>Consolidated Feature Scopes</strong></td><td style="text-align:left;"><code>admin-crawler-control</code>, <code>admin-multiplatform-trend-pipeline</code>, <code>admin-trend-data-view</code>, <code>admin-trend-pipeline-now</code>, <code>admin-trend-source-config</code>, <code>crawler-bounded-memory</code>, <code>crawler-proxy-readiness</code>, <code>internal-trends-fetch</code>, <code>update-trend-flow</code>, <code>trend-cold-storage</code>, <code>trend-s3-daily-replay</code>, <code>trend-review-cli</code>, <code>ai-service-ci</code></td></tr><tr><td style="text-align:left;"><strong>Aligned SRS Domains</strong></td><td style="text-align:left;"><a href="./../../../srs/06-ai-features/3-7-1-view-trending-topics-suggestions/spec.html">FR 3.7.1 — View Trending Topics</a> · <a href="./../../../srs/06-ai-features/3-7-13-crawl-schedule-config/spec.html">FR 3.7.13 — Crawl Schedule Config</a></td></tr><tr><td style="text-align:left;"><strong>Status</strong></td><td style="text-align:left;">Implemented — Production Verified</td></tr></tbody></table><h2 id="_1-objective-architectural-motivation" tabindex="-1">1. Objective &amp; Architectural Motivation <a class="header-anchor" href="#_1-objective-architectural-motivation" aria-label="Permalink to &quot;1. Objective &amp; Architectural Motivation&quot;">​</a></h2><p>Orchestrate BrandHub&#39;s end-to-end <strong>Multi-Platform Trend Ingestion &amp; Labeling Pipeline (<code>T0 -&gt; T7</code>)</strong>: <code>Admin</code> crawler credential/proxy health probes &amp; live run controls (<code>AdminCrawlerManagementController</code>, <code>AdminTrendPipelineController</code>), bounded-memory headless/API crawlers (<code>crawler-bounded-memory</code>, <code>crawler-proxy-readiness</code>), lean LLM trend clustering &amp; naming (<code>update-trend-flow</code>, <code>trend-review-cli</code>), internal <code>/fetch</code> &amp; <code>/dependencies</code> contracts, <strong>S3 Daily Cold Storage &amp; Deterministic Historical Replay</strong> (<code>AdminTrendReplayController</code>), and <code>brandhub-ai-service</code> CI gates.</p><h2 id="_2-user-stories" tabindex="-1">2. User Stories <a class="header-anchor" href="#_2-user-stories" aria-label="Permalink to &quot;2. User Stories&quot;">​</a></h2><ul><li>As an <code>Admin</code>, I want full visibility and manual/scheduled control over multi-platform trend crawlers, rotating proxy &amp; cookie probes, immediate &#39;Run Pipeline Now&#39; triggers, raw trend data inspection, and deterministic S3 daily historical replay without memory leaks or duplicate Neo4j/Redis ingestion.</li></ul><h2 id="_3-consolidated-acceptance-criteria" tabindex="-1">3. Consolidated Acceptance Criteria <a class="header-anchor" href="#_3-consolidated-acceptance-criteria" aria-label="Permalink to &quot;3. Consolidated Acceptance Criteria&quot;">​</a></h2><ol><li><strong>Unified Admin Crawler &amp; Source Control (<code>admin-crawler-control</code>, <code>admin-multiplatform-trend-pipeline</code>, <code>admin-trend-source-config</code>, <code>admin-trend-pipeline-now</code>, <code>admin-trend-data-view</code>):</strong> <code>AdminCrawlerManagementController</code> (<code>/api/v1/admin/ai/trend-pipeline/management/{health|credentials|preview|start|runs}</code>) and <code>AdminTrendPipelineController</code> (<code>/config</code>, <code>/source-config</code>, <code>/runs</code>, <code>/recover</code>) let <code>Admin</code> configure source weights, probe/revoke encrypted cookies/proxies, trigger on-demand runs, recover stalled runs, and inspect normalized trend items (<code>AdminTrendController</code>).</li><li><strong>Bounded-Memory Execution &amp; Proxy Rotation (<code>crawler-bounded-memory</code>, <code>crawler-proxy-readiness</code>):</strong> <code>crawl_batch_consumer.py</code> enforces strict batch streaming, browser context recycling, and health-checked proxy rotation so long crawl batches stay within container memory limits.</li><li><strong>Lean <code>T0 -&gt; T7</code> LLM Labeling &amp; Internal Fetch Contract (<code>update-trend-flow</code>, <code>trend-review-cli</code>, <code>internal-trends-fetch</code>):</strong> Raw scraped items deduplicate (<code>trend_dedup.py</code>), cluster, label via structured LLM/Claude CLI review prompts, publish to Redis ZSETs (<code>trends:vn:*</code>) + Neo4j (<code>knowledge_graph.py</code>), and expose <code>GET /api/v1/ai/internal/trends/fetch</code> &amp; <code>/dependencies</code> (<code>X-Internal-Api-Key</code>).</li><li><strong>S3 Cold Storage &amp; Daily Replay (<code>trend-cold-storage</code>, <code>trend-s3-daily-replay</code>):</strong> Every crawl batch archives immutable compressed NDJSON/JSON envelopes to S3 (<code>trend_cold_storage.py</code>); <code>AdminTrendReplayController</code> (<code>/api/v1/admin/ai/trend-replays/preview</code>, <code>/{identity}/start|cancel|days/{day}</code>) replays archived S3 days idempotently to rebuild Redis/Neo4j state.</li><li><strong>Internationalization (<code>vi.json</code> + <code>en.json</code>):</strong> Every user-facing string, tooltip, dialog prompt, status badge, and error banner uses key-parallel translations (<code>admin.crawler.*</code>, <code>admin.trendPipeline.*</code>, <code>admin.trendReplay.*</code> in <code>src/i18n/locales/{vi,en}/admin.json</code>) on <code>brandhub-web</code> and <code>tr()</code> (<code>en.json</code> + <code>vi/common.json</code>) on <code>brandhub-mobile-app</code> with zero hardcoded Vietnamese or English strings in JSX/TSX.</li><li><strong>Light &amp; Dark Mode Compliance:</strong> All surfaces, drawers, badges, charts, and interactive controls use semantic CSS variables / Tailwind <code>dark:</code> variants on Web and <code>useAppPreferences().palette</code> tokens on Mobile, achieving WCAG AA contrast in both Light and Dark themes.</li></ol><h2 id="_4-ui-ux-surfaces-lifecycle-states" tabindex="-1">4. UI / UX Surfaces &amp; Lifecycle States <a class="header-anchor" href="#_4-ui-ux-surfaces-lifecycle-states" aria-label="Permalink to &quot;4. UI / UX Surfaces &amp; Lifecycle States&quot;">​</a></h2><ul><li><strong>Web Surfaces (<code>brandhub-web</code>):</strong> <code>pages/admin/components/{AdminTrendPipelinePanel,AdminTrendPipelineControl,AdminTrendSourceConfig,CrawlerCredentialsPanel,CrawlerHealthPanel,CrawlerRunLauncher,AdminTrendReplayPanel,TrendReplayFlow}.tsx</code></li><li><strong>Mobile Surfaces (<code>brandhub-mobile-app</code>):</strong> <code>src/components/admin/AdminCrawlerHealthCard.tsx</code>, <code>src/screens/admin/AdminSystemHealthScreen.tsx</code></li><li><strong>UI States:</strong><ul><li><strong>Loading / Streaming:</strong> Deterministic skeleton placeholders, progress bars, and disabled submit buttons preventing duplicate requests.</li><li><strong>Empty / Onboarding:</strong> Contextual empty state with localized call-to-action and zero fabricated mock fallback data.</li><li><strong>Active / Realtime Sync:</strong> Scoped <code>TanStack Query</code> cache updates + WebSocket/SSE/polling synchronization where applicable.</li><li><strong>Error / Conflict Recovery:</strong> Actionable localized error banners (<code>400/403/404/409/429/503</code>) preserving unsaved user input.</li></ul></li></ul><h2 id="_5-api-messaging-protocol-contract" tabindex="-1">5. API, Messaging &amp; Protocol Contract <a class="header-anchor" href="#_5-api-messaging-protocol-contract" aria-label="Permalink to &quot;5. API, Messaging &amp; Protocol Contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Route / Channel / Filter</th><th style="text-align:left;">Auth / Scope</th><th style="text-align:left;">Service &amp; Handler</th></tr></thead><tbody><tr><td style="text-align:left;"><code>GET/PATCH/POST /api/v1/admin/ai/trend-pipeline/** &amp; /management/**</code></td><td style="text-align:left;">Bearer (<code>Admin</code>)</td><td style="text-align:left;"><code>AdminTrendPipelineController</code> &amp; <code>AdminCrawlerManagementController</code> -&gt; schedule, source config, credential probes &amp; run lifecycle</td></tr><tr><td style="text-align:left;"><code>GET /api/v1/admin/ai/trends &amp; /summary</code></td><td style="text-align:left;">Bearer (<code>Admin</code>)</td><td style="text-align:left;"><code>AdminTrendController</code> -&gt; inspect ingested multi-platform trend records</td></tr><tr><td style="text-align:left;"><code>POST/GET /api/v1/admin/ai/trend-replays/**</code></td><td style="text-align:left;">Bearer (<code>Admin</code>)</td><td style="text-align:left;"><code>AdminTrendReplayController</code> -&gt; <code>trend_replays.py</code> S3 cold-storage preview &amp; daily replay</td></tr><tr><td style="text-align:left;"><code>GET /api/v1/ai/internal/trends/fetch &amp; /dependencies</code></td><td style="text-align:left;"><code>X-Internal-Api-Key</code></td><td style="text-align:left;"><code>internal_trends.py</code> (<code>brandhub-ai-service</code>) -&gt; internal snapshot &amp; store readiness contract</td></tr></tbody></table><h2 id="_6-error-handling-security-edge-cases" tabindex="-1">6. Error Handling, Security &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-security-edge-cases" aria-label="Permalink to &quot;6. Error Handling, Security &amp; Edge Cases&quot;">​</a></h2><ul><li><strong>Proxy / Platform Cookie Expired Mid-Run:</strong> Credential probe marks source degraded, isolates failure to that source (<code>trend_dlq.py</code>), and completes remaining sources without aborting the entire pipeline.</li><li><strong>Cancelled or Concurrent Pipeline Run:</strong> Distributed Redis run lock prevents overlapping <code>T0 -&gt; T7</code> mutations; <code>/recover</code> cleans orphaned locks.</li></ul><h2 id="_7-related-specifications-references" tabindex="-1">7. Related Specifications &amp; References <a class="header-anchor" href="#_7-related-specifications-references" aria-label="Permalink to &quot;7. Related Specifications &amp; References&quot;">​</a></h2><ul><li><strong>Aligned SRS Functional Requirements:</strong> <a href="./../../../srs/06-ai-features/3-7-1-view-trending-topics-suggestions/spec.html">FR 3.7.1 — View Trending Topics</a> · <a href="./../../../srs/06-ai-features/3-7-13-crawl-schedule-config/spec.html">FR 3.7.13 — Crawl Schedule Config</a></li><li><strong>BA &amp; Architecture References:</strong> <a href="./../../../../ba/06-ai-features.html">BA 06 AI Features</a> · <a href="./../../../../ba/10-roles-permissions-matrix.html">Roles &amp; Permissions Matrix</a></li></ul><h2 id="_8-definition-of-done-out-of-scope" tabindex="-1">8. Definition of Done &amp; Out of Scope <a class="header-anchor" href="#_8-definition-of-done-out-of-scope" aria-label="Permalink to &quot;8. Definition of Done &amp; Out of Scope&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Production code verified across backend, AI/publisher workers, Web, and Mobile; <code>vi.json</code> + <code>en.json</code> parity verified; Light/Dark mode audited; all automated verification suites in <a href="./test.html">test.md</a> passing.</li><li><strong>Out of Scope:</strong> De-scoped SRS items (livestream features, subscription plan downgrades, PayOS/VNPay/Stripe gateways, Zalo OA publishing, or copyright/plagiarism scanning).</li></ul>',19)])])}const u=t(n,[["render",d]]);export{g as __pageData,u as default};
